css:
.servesells-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1d2733;
    background: linear-gradient(165deg, #f5f7fa 0%, #eef3f4 55%, #e9f0ee 100%);
    border-radius: 18px;
}

.servesells-container * {
    box-sizing: border-box;
}

.servesells-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #0a2f4f 0%, #11506b 55%, #15786e 100%);
    color: #f3fafb;
    border-radius: 16px;
    margin-bottom: 18px;
    box-shadow: 0 14px 34px rgba(10, 47, 79, 0.30);
}

.servesells-header h1 {
    margin: 10px 0 10px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.servesells-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #f3c969;
    background: rgba(243, 201, 105, 0.14);
    border: 1px solid rgba(243, 201, 105, 0.40);
    padding: 5px 14px;
    border-radius: 999px;
}

.servesells-subtitle {
    margin: 0 auto;
    max-width: 840px;
    font-size: 1rem;
    line-height: 1.55;
    color: #d4ecec;
}

.servesells-chain {
    display: flex;
    align-items: stretch;
    gap: 10px;
    margin-bottom: 18px;
}

.servesells-chain-node {
    flex: 1;
    background: #ffffff;
    border-radius: 14px;
    padding: 13px 16px;
    box-shadow: 0 4px 14px rgba(29, 39, 51, 0.08);
    display: flex;
    flex-direction: column;
    gap: 4px;
    border-left: 5px solid #11506b;
}

.servesells-node-internal { border-left-color: #c2792c; }
.servesells-node-engage { border-left-color: #2b6cb0; }
.servesells-node-customer { border-left-color: #15786e; }

.servesells-chain-label {
    font-weight: 800;
    font-size: 1.02rem;
    color: #0a2f4f;
}

.servesells-node-internal .servesells-chain-label { color: #b16b1f; }
.servesells-node-engage .servesells-chain-label { color: #2b6cb0; }
.servesells-node-customer .servesells-chain-label { color: #157561; }

.servesells-chain-meta {
    font-size: 0.8rem;
    color: #5a6b7a;
    line-height: 1.4;
}

.servesells-chain-arrow {
    align-self: center;
    font-size: 1.5rem;
    font-weight: 800;
    color: #15786e;
}

.servesells-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #44586a;
    margin-bottom: 16px;
    padding: 4px 4px;
}

.servesells-period-counter #currentDay,
.servesells-period-counter #maxPeriods {
    font-weight: 800;
    color: #15786e;
}

.servesells-round-name {
    background: rgba(21, 120, 110, 0.14);
    color: #137061;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.servesells-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #b16b1f;
    background: rgba(194, 121, 44, 0.14);
    border: 1px solid rgba(194, 121, 44, 0.30);
    padding: 4px 12px;
    border-radius: 999px;
}

.servesells-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.servesells-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    box-shadow: 0 6px 16px rgba(29, 39, 51, 0.08);
    border-top: 4px solid #11506b;
}

.servesells-card-sat { border-top-color: #15786e; }
.servesells-card-gap { border-top-color: #c2792c; }
.servesells-card-brand { border-top-color: #2b6cb0; }
.servesells-card-roi { border-top-color: #6b5fbf; }

.servesells-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #69798a;
}

.servesells-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #0a2f4f;
    font-variant-numeric: tabular-nums;
}

.servesells-card-sat .servesells-value { color: #15786e; }
.servesells-card-gap .servesells-value { color: #c2792c; }
.servesells-card-brand .servesells-value { color: #2b6cb0; }
.servesells-card-roi .servesells-value { color: #6b5fbf; }

.servesells-sublabel {
    font-size: 0.76rem;
    color: #76889a;
    line-height: 1.35;
}

/* The headline KPI — satisfaction — gets the strongest colour story. */
.servesells-card-sat {
    border: 1px solid #d7e6e2;
    border-top-width: 5px;
    box-shadow: 0 8px 22px rgba(21, 120, 110, 0.16);
}
.servesells-card-sat.servesells-sat-danger { border-top-color: #d6453f; }
.servesells-card-sat.servesells-sat-danger .servesells-value { color: #d6453f; }
.servesells-card-sat.servesells-sat-warn { border-top-color: #c2792c; }
.servesells-card-sat.servesells-sat-warn .servesells-value { color: #c2792c; }
.servesells-card-sat.servesells-sat-good { border-top-color: #15876b; }
.servesells-card-sat.servesells-sat-good .servesells-value { color: #15876b; }

.servesells-card-gap.servesells-gap-good .servesells-value { color: #15876b; }
.servesells-card-gap.servesells-gap-bad .servesells-value { color: #d6453f; }

.servesells-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #ffffff;
    border: 1px solid #e0e6ea;
    color: #44586a;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.servesells-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #11506b;
    font-weight: 800;
    font-variant-numeric: tabular-nums;
}

.servesells-budget-bar.servesells-budget-over #budgetDisplay { color: #d6453f; }
.servesells-budget-bar.servesells-budget-full #budgetDisplay { color: #15876b; }

.servesells-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #15786e;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(29, 39, 51, 0.07);
}

.servesells-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.servesells-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #0a2f4f;
    margin-bottom: 6px;
}

.servesells-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #3a4b5c;
}

.servesells-briefing-text strong { color: #11506b; }
.servesells-briefing-text em { color: #c2792c; font-style: italic; }

.servesells-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(29, 39, 51, 0.07);
}

.servesells-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #0a2f4f;
    border-bottom: 2px solid #e6ecef;
    padding-bottom: 8px;
}

.servesells-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2a3b4c;
    margin: 14px 0 6px;
}

.servesells-container select,
.servesells-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c6d1d8;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #ffffff;
    color: #1d2733;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.servesells-container select:focus,
.servesells-container input[type="number"]:focus {
    outline: none;
    border-color: #15786e;
    box-shadow: 0 0 0 3px rgba(21, 120, 110, 0.16);
}

.servesells-container select option {
    background-color: #ffffff;
    color: #1d2733;
}

.servesells-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #15786e;
}

.servesells-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #44586a;
    margin-top: 4px;
}

.servesells-range-readout span:nth-child(2) {
    color: #15786e;
    font-weight: 800;
}

.servesells-hint {
    font-size: 0.8rem;
    color: #76889a;
    margin-top: 6px;
    line-height: 1.4;
    font-style: italic;
}

.servesells-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.servesells-container .btn-primary {
    background: linear-gradient(135deg, #11506b 0%, #15786e 100%);
    border: none;
    color: #ffffff;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(17, 80, 107, 0.32);
}

.servesells-container .btn-primary:hover {
    filter: brightness(1.07);
}

.servesells-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #c6d1d8;
    color: #5a6b7a;
    background: transparent;
}

.servesells-coach {
    background: linear-gradient(160deg, #0a2f4f 0%, #0d3a55 100%);
    color: #e2f1f0;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(10, 47, 79, 0.24);
}

.servesells-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #f3c969;
    margin-bottom: 8px;
}

.servesells-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.servesells-coach-body strong { color: #7fe0d0; }
.servesells-coach-body em { color: #f3c969; font-style: italic; }

.servesells-history,
.servesells-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(29, 39, 51, 0.07);
}

.servesells-history h3,
.servesells-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #0a2f4f;
}

.servesells-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #3a4b5c;
}

.servesells-container table#usfHistoryTable th {
    background: #eef4f3;
    color: #11506b;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d7e3e1;
}

.servesells-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef1f3;
    color: #3a4b5c;
}

.servesells-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f7faf9;
}

.servesells-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .servesells-container {
        padding: 14px;
    }
    .servesells-header h1 {
        font-size: 1.7rem;
    }
    .servesells-chain {
        flex-direction: column;
    }
    .servesells-chain-arrow {
        transform: rotate(90deg);
    }
    .servesells-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .servesells-value {
        font-size: 2rem;
    }
    .servesells-clock {
        margin-left: 0;
    }
    .servesells-period-counter {
        font-size: 0.88rem;
    }
    .servesells-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .servesells-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* ============================================================
   Service That Sells — completion debrief (v1.1.0, append-only)
   Namespaced .sts-cm-* ; rendered into #usf-completion-content.
   ============================================================ */
.sts-cm { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Arial, sans-serif; color: #1f2a37; }
.sts-cm-verdict { display: flex; align-items: center; gap: 18px; padding: 16px 18px; border-radius: 12px;
    background: linear-gradient(135deg, #eef3fb 0%, #f2f7f6 100%); border: 1px solid #dce4ee; margin-bottom: 18px; }
.sts-cm-top .sts-cm-verdict { background: linear-gradient(135deg, #e6f0fb 0%, #e5f4ee 100%); border-color: #2b6cb0; }
.sts-cm-score { flex: 0 0 auto; min-width: 92px; text-align: center; line-height: 1; }
.sts-cm-score-num { font-size: 2.9rem; font-weight: 800; color: #2b6cb0; }
.sts-cm-score-den { font-size: 1.1rem; font-weight: 600; color: #7688a0; }
.sts-cm-top .sts-cm-score-num { color: #1f6f5c; }
.sts-cm-verdict-txt { flex: 1 1 auto; }
.sts-cm-badge { font-size: 1.35rem; font-weight: 700; color: #1f2a37; margin-bottom: 3px; }
.sts-cm-sub { font-size: 0.9rem; color: #7688a0; }
.sts-cm-h { font-size: 0.82rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.05em;
    color: #46596b; margin: 16px 0 8px; }
.sts-cm-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.sts-cm-chip { display: inline-flex; align-items: center; gap: 5px; padding: 5px 11px; border-radius: 16px;
    font-size: 0.86rem; font-weight: 600; border: 1px solid transparent; }
.sts-cm-chip-ok { background: rgba(43,108,176,0.10); color: #1f6f5c; border-color: rgba(31,111,92,0.30); }
.sts-cm-chip-no { background: rgba(214,69,69,0.10); color: #b23b3b; border-color: rgba(214,69,69,0.30); }
.sts-cm-kpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(110px, 1fr)); gap: 10px; }
.sts-cm-kpi { background: #f6f9fc; border: 1px solid #e5edf4; border-radius: 10px; padding: 11px 12px; text-align: center; }
.sts-cm-kpi-val { font-size: 1.25rem; font-weight: 800; color: #1f2a37; }
.sts-cm-kpi-lbl { font-size: 0.76rem; font-weight: 600; color: #46596b; margin-top: 3px; line-height: 1.2; }
.sts-cm-kpi-sub { font-size: 0.7rem; color: #93a3b3; margin-top: 2px; }
.sts-cm-insights { margin: 0; padding-left: 18px; }
.sts-cm-insights li { font-size: 0.9rem; line-height: 1.5; color: #33414f; margin-bottom: 7px; }
.usf-dark .sts-cm { color: #e6edf3; }
.usf-dark .sts-cm-verdict { background: linear-gradient(135deg, #1a2432 0%, #1a2a28 100%); border-color: #2c3a4c; }
.usf-dark .sts-cm-badge { color: #e6edf3; }
.usf-dark .sts-cm-kpi { background: #1a2230; border-color: #2a3646; }
.usf-dark .sts-cm-kpi-val { color: #e6edf3; }
.usf-dark .sts-cm-insights li { color: #c4d0dc; }

/* EQIL 2026-11 accessibility and debrief additions, namespaced */
.servesells-container select:focus-visible, .servesells-container input:focus-visible, .servesells-container button:focus-visible { outline: 3px solid #1d4ed8; outline-offset: 2px; }
.sts-cm-turning { margin: 4px 0 10px; font-weight: 600; }
.sts-cm-questions { margin: 4px 0 0 18px; padding: 0; }
.sts-cm-questions li { margin: 2px 0; }
@media (prefers-reduced-motion: reduce) { .servesells-container *, .sts-cm * { transition: none !important; animation: none !important; } }

