                roi: ds.roi,
                engagement: ds.engagement,
                promise: ds.promise,
                actualTime: ds.actualTime,
                spent: ds.spent,
                overPromiseRun: ds.overPromiseRun,
                adFixRun: ds.adFixRun,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg,
                score: _score,
                overallScore: _score
            };
        }

        _satClass(v) {
            if (v < this.FLOOR_SAT) return `danger`;
            if (v < this.TARGET_SAT) return `warn`;
            return `good`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`satDisplay`, `domainState.sat`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.servesells-card-sat`);
                if (card) {
                    card.classList.toggle(`servesells-sat-danger`, n < self.FLOOR_SAT);
                    card.classList.toggle(`servesells-sat-warn`, n >= self.FLOOR_SAT && n < self.TARGET_SAT);
                    card.classList.toggle(`servesells-sat-good`, n >= self.TARGET_SAT);
                }
                return `${self._fmtNum(n, 0)}%`;
            });

            uiManager.bind(`gapDisplay`, `domainState.gap`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.servesells-card-gap`);
                if (card) {
                    card.classList.toggle(`servesells-gap-good`, n <= 1.0);
                    card.classList.toggle(`servesells-gap-bad`, n >= 1.6);
                }
                return self._fmtNum(n, 1);
            });

            uiManager.bind(`brandDisplay`, `domainState.brand`, (v) => `${self._fmtNum(Number(v), 0)}`);

            uiManager.bind(`roiDisplay`, `domainState.roi`, (v) => `${self._fmtNum(Number(v), 2)}×`);

            uiManager.bind(`budgetDisplay`, `domainState.spent`, (v) => {
                const n = Number(v);
                const bar = document.querySelector(`.servesells-budget-bar`);
                if (bar) {
                    bar.classList.toggle(`servesells-budget-over`, n > self.BUDGET);
                    bar.classList.toggle(`servesells-budget-full`, n >= self.BUDGET * 0.85 && n <= self.BUDGET);
                }
                return `₱${self._fmtNum(n, 0)}M / ₱${self.BUDGET}M`;
            });

            // Inaction slider readout.
            const ia = document.getElementById(`inactionInput`);
            const iaReadout = document.getElementById(`inactionReadout`);
            if (ia && iaReadout) {
                iaReadout.textContent = ia.value;
                ia.addEventListener(`input`, function() { iaReadout.textContent = ia.value; });
            }

            // Accessibility: mirror each control's visible (data-i18n) prompt onto the
            // control via aria-label — the prompts are separate elements (no <label for>),
            // so a screen reader would otherwise announce an unlabeled <select>. t() keeps
            // the label correct in each language.
            const tA = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            const ariaMap = {
                rootInput: `r1_root_label`, dimInput: `r1_dim_label`, symptomInput: `r1_symptom_label`,
                inactionInput: `r1_inaction_label`, slaInput: `r2_sla_label`, empowerInput: `r2_empower_label`,
                cultureInput: `r2_culture_label`, internalBudgetInput: `r2_internalbudget_label`,
                promiseInput: `r3_promise_label`, advertisingInput: `r3_advertising_label`,
                serviceInput: `r3_service_label`, internalTopupInput: `r3_topup_label`,
                defenseInput: `r4_defense_label`, shockInput: `r4_shock_label`,
                indicatorInput: `r4_indicator_label`, holdInput: `r4_hold_label`
            };
            Object.keys(ariaMap).forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.setAttribute(`aria-label`, tA(ariaMap[id]));
            });
            const cv = document.getElementById('serveChart');
            if (cv) { cv.setAttribute('role', 'img'); cv.setAttribute('aria-label', tA('chart_alt')); }
        }

        _fmtNum(v, decimals) {
            // Locale-aware number: en "1.8", es "1,8".
            const lang = (window.vcI18n && window.vcI18n._lang) || (window.mySimulation && window.mySimulation.language) || document.documentElement.lang || 'en';
            const s = Number(v).toFixed(decimals);
            return lang === `es` ? s.replace(`.`, `,`) : s;
        }

        getChartConfig() {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            return {
                serveChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: t(`chart_ds_sat`),
                                data: [],
                                borderColor: `#15786e`,
