                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState || {};
            const labels = (ds.satHistory || []).map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            // Gap is 0–3 — scale ×20 to share the 0–100 axis with the percentages and the index.
            const gapScaled = (ds.gapHistory || []).map((v) => Math.round(v * 20));
            return {
                serveChart: {
                    labels: labels,
                    datasets: [
                        { data: (ds.satHistory || []).map((v) => Math.round(v * 10) / 10) },
                        { data: (ds.brandHistory || []).map((v) => Math.round(v)) },
                        { data: gapScaled }
                    ]
                }
            };
        }

        // ---- Composite score — single source of truth. ----
        // Carries the VERBATIM v1.0.0 getPerformanceSummary formula so the score
        // persisted every period equals the completion composite by construction.
        _composite(ds) {
            const sat   = Math.round(ds.sat * 10) / 10;
            const brand = Math.round(ds.brand);
            const gap   = Math.round(ds.gap * 100) / 100;
            const roi   = Math.round(ds.roi * 100) / 100;
            const gapScore = Math.max(0, (3 - gap) / 3) * 100;
            const roiScore = Math.min(100, roi * 60);
            return Math.round(sat * 0.40 + brand * 0.22 + gapScore * 0.22 + roiScore * 0.16);
        }

        // Map the (stable, English) performance tier id to its localized label.
        _gradeLabel(performance) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            const map = {
                'Service Brand Restored': `grade_restored`,
                'Target Hit':             `grade_target`,
                'Advertised the Fix':     `grade_adfix`,
                'Price-War Pivot':        `grade_pivot`,
                'Mixed Recovery':         `grade_mixed`,
                'Brand at Risk':          `grade_atrisk`
            };
            return t(map[performance] || `grade_atrisk`);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const sat = Math.round(ds.sat * 10) / 10;
            const brand = Math.round(ds.brand);
            const gap = Math.round(ds.gap * 100) / 100;
            const roi = Math.round(ds.roi * 100) / 100;

            const hitTarget = sat >= this.TARGET_SAT;
            const aboveFloor = sat >= this.FLOOR_SAT;
            const gapClosed = gap <= 1.0;
            const brandRecovered = brand >= this.START_BRAND;
            const internalLed = ds.internalSpent >= 100 && !ds.adFixRun;

            // Composite — computed by _composite(), the SAME helper persisted to
            // domainState.performance.overallScore each period, so the completion score
            // equals the last per-period score by construction.
            const composite = this._composite(ds);

            let pattern = `mixed`;
            if (ds.adFixRun || ds.overPromiseRun) pattern = `adfix`;
            else if (internalLed && gapClosed && hitTarget) pattern = `orientation`;
            else if (ds.misdiagnosed && !internalLed) pattern = `misdiagnosed`;

            let performance = `Brand at Risk`;
            if (hitTarget && gapClosed && brandRecovered && internalLed && composite >= 73) performance = `Service Brand Restored`;
            else if (hitTarget && internalLed && !ds.adFixRun) performance = `Target Hit`;
            else if (ds.adFixRun && sat < this.TARGET_SAT) performance = `Advertised the Fix`;
            else if (!aboveFloor) performance = `Price-War Pivot`;
            else if (composite >= 58) performance = `Mixed Recovery`;

            // Debrief built from the run history: each run-defining move is named in the round it was made,
            // and the earliest one is the turning point. Nothing is said about a move the player did not make.
            const tr = (k) => window.mySimulation.t(k);
            const moves = this._runMoves(history, ds);
            const insights = [];
            if (pattern === 'orientation') insights.push(tr('insight_orientation'));
            moves.forEach((m) => {
                insights.push(tr(m.key).split('{p}').join(String(ds.promise)).split('{t}').join(String(ds.actualTime)));
            });
            if (!moves.length && pattern !== 'orientation') insights.push(tr('insight_mixed'));
            if (!aboveFloor) insights.push(tr('insight_floor'));
            if (!gapClosed) insights.push(tr('insight_gap_open'));
            if (hitTarget && !brandRecovered) insights.push(tr('insight_brand_lag'));
            if (ds.overBudget) insights.push(tr('insight_overbudget'));
            const turning = moves.length ? { round: moves[0].round, label: tr(moves[0].tp) } : null;

            return {
                sat: sat,
                brand: brand,
                gap: gap,
                roi: roi,
                hitTarget: hitTarget,
                aboveFloor: aboveFloor,
                gapClosed: gapClosed,
                brandRecovered: brandRecovered,
                internalLed: internalLed,
                pattern: pattern,
                composite: composite,
                performance: performance,
                performanceLabel: this._gradeLabel(performance),
                insights: insights,
                turning: turning
            };
        }

        // The run-defining moves this run actually made, in round order, read from the history.
        _runMoves(history, ds) {
            const h = Array.isArray(history) ? history : [];
            const dec = (r) => (h[r - 1] && h[r - 1].decisions) || {};
            const st = (r) => (h[r - 1] && h[r - 1].domainState) || {};
            const out = [];
            const add = (round, key, tp) => out.push({ round: round, key: key, tp: tp });
            if (h.length >= 1) {
                const d1 = dec(1);
                if (d1.root === 'frontline') add(1, 'insight_counter', 'tp_counter');
                else if (d1.root === 'advertising') add(1, 'insight_diag_ads', 'tp_diag_ads');
                else if (d1.root === 'customers') add(1, 'insight_diag_customers', 'tp_diag_customers');
                else if (d1.symptom === 'cause_ads') add(1, 'insight_symptom_ads', 'tp_diag_ads');
                else if (d1.symptom === 'both_symptom') add(1, 'insight_symptom_both', 'tp_symptom_both');
            }
            if (h.length >= 2) {
                const d2 = dec(2);
                if (d2.sla === 'mandate') add(2, 'insight_sla', 'tp_sla');
                else if (d2.sla === 'resourced' && d2.culture === 'orders') add(2, 'insight_sla_orders', 'tp_sla_orders');
            }
            if (h.length >= 3) {
                const d3 = dec(3);
                const s3 = st(3);
                const s2 = st(2);
                if (s3.overPromiseRun) add(3, 'insight_overpromise', 'tp_overpromise');
                if (String(d3.advertising) === '350' && s3.adFixRun && !s2.adFixRun) {
                    if (s3.overPromiseRun) add(3, 'insight_adfix', 'tp_adfix');
                    else add(3, 'insight_adfix_underfunded', 'tp_adfix_under');
                }
            }
            if (h.length >= 4) {
                const d4 = dec(4);
                if (d4.shock === 'neobank') add(4, 'insight_neobank', 'tp_neobank');
                if (d4.shock === 'cfocut') add(4, 'insight_cfocut', 'tp_cfocut');
                if (d4.defense === 'deny') add(4, 'insight_lag_denied', 'tp_lag_denied');
                if (d4.indicator === 'awareness' || d4.indicator === 'satisfaction') {
                    add(4, d4.indicator === 'awareness' ? 'insight_ind_awareness' : 'insight_ind_satisfaction', 'tp_indicator');
                }
            }
            return out;
        }

        // Localized completion debrief — the base class default only prints
        // "You completed N periods", discarding the composite, tier, targets,
        // KPIs and insights this sim computes. Rendered into #usf-completion-content.
        formatCompletionMessage(summary) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            const s = summary || {};
            const composite = Number.isFinite(s.composite) ? s.composite : this._composite(window.mySimulation.state.domainState);
            const verdict = s.performanceLabel || this._gradeLabel(s.performance || `Brand at Risk`);
            const top = (s.performance === `Service Brand Restored`);
            const fmt = this._fmtNum.bind(this);
            const chip = (ok, label) =>
                `<span class="sts-cm-chip ${ok ? `sts-cm-chip-ok` : `sts-cm-chip-no`}">${ok ? `✓` : `✗`} ${label}</span>`;
            const kpi = (label, value, sub) =>
                `<div class="sts-cm-kpi"><div class="sts-cm-kpi-val">${value}</div>` +
                `<div class="sts-cm-kpi-lbl">${label}</div>` + (sub ? `<div class="sts-cm-kpi-sub">${sub}</div>` : ``) + `</div>`;
            const chips = [
                chip(!!s.hitTarget,      t(`cm_t_target`)),
                chip(!!s.gapClosed,      t(`cm_t_gap`)),
                chip(!!s.brandRecovered, t(`cm_t_brand`)),
                chip(!!s.internalLed,    t(`cm_t_internal`)),
                chip(!!s.aboveFloor,     t(`cm_t_floor`))
            ].join(``);
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const insightsHtml = insights.length
                ? `<div class="sts-cm-h">${t(`cm_insights_h`)}</div><ul class="sts-cm-insights">` +
                  insights.map((x) => `<li>${x}</li>`).join(``) + `</ul>` : ``;
            const tp = s.turning;
            const turningHtml = '<div class="sts-cm-h">' + t('cm_turning_h') + '</div><p class="sts-cm-turning">' +
                (tp ? t('round_label') + ' ' + tp.round + ': ' + tp.label : t('cm_turning_none')) + '</p>';
            const questionsHtml = '<div class="sts-cm-h">' + t('cm_questions_h') + '</div><ol class="sts-cm-questions">' +
                ['cm_q1', 'cm_q2', 'cm_q3'].map((k) => '<li>' + t(k) + '</li>').join('') + '</ol>';
            return `
                <div class="sts-cm ${top ? `sts-cm-top` : ``}">
                    <div class="sts-cm-verdict">
                        <div class="sts-cm-score"><span class="sts-cm-score-num">${composite}</span><span class="sts-cm-score-den">/100</span></div>
                        <div class="sts-cm-verdict-txt">
                            <div class="sts-cm-badge">${verdict}</div>
                            <div class="sts-cm-sub">${t(`cm_periods_pre`)} ${s.totalPeriods || 4} ${t(`cm_periods_post`)}</div>
                        </div>
                    </div>
                    <div class="sts-cm-h">${t(`cm_targets_h`)}</div>
                    <div class="sts-cm-chips">${chips}</div>
                    <div class="sts-cm-h">${t(`cm_kpis_h`)}</div>
                    <div class="sts-cm-kpis">
                        ${kpi(t(`sat_label`), fmt(Number(s.sat) || 0, 0) + `%`, t(`cm_target`) + ` 75%`)}
                        ${kpi(t(`gap_label`), fmt(Number(s.gap) || 0, 1), t(`cm_target`) + ` ≤1.0`)}
                        ${kpi(t(`brand_label`), Math.round(Number(s.brand) || 0), t(`cm_from`) + ` 58`)}
                        ${kpi(t(`roi_label`), fmt(Number(s.roi) || 0, 2) + `×`, `ROI`)}
                    </div>
                    ${turningHtml}
                    ${insightsHtml}
                    ${questionsHtml}
                </div>
            `;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.sat < this.FLOOR_SAT) return window.mySimulation.t(`hint_floor`);
            if (ds.overPromiseRun) return window.mySimulation.t(`hint_overpromise`);
            if (ds.adFixRun) return window.mySimulation.t(`hint_adfix`);
            if (ds.misdiagnosed && state.currentPeriod < 3) return window.mySimulation.t(`hint_misdiagnosed`);
            if (ds.internalSpent < 100 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_internal`);
            if (ds.sat >= this.TARGET_SAT && ds.gap <= 1.0) return window.mySimulation.t(`hint_strong`);
            return null;
        }

